			ctx := types.NewRoutingContext(context.Background(), routing.RouterPrefixCache, "qwen-vl", "", "epd-inflight", "")
			defer ctx.Delete()
			ctx.ConfigProfile = &types.ResolvedConfigProfile{RequestsInflight: tc.limit}
			ctx.ReqPath = "/v1/chat/completions"
			ctx.ReqBody = []byte(`{"model":"qwen-vl","messages":[{"role":"user","content":[{"type":"image_url","image_url":{"url":"https://x/a.png"}}]}]}`)
			_, err := s.selectTargetPod(context.Background(), ctx, &utils.PodArray{Pods: pods}, "")
			require.NoError(t, err)
